        davenport_k->m[i + 1][0] = z[i];
        for (j = 0; j < 3; j++)
            davenport_k->m[i + 1][j + 1] =
                b.m[i][j] + b.m[j][i] - ((i == j) ? sigma : 0.0);
    }
    *weight_sum = ws;
    return ADCS_OK;
}

candidates.misra:
    size_t n, i, j;
    adcs_mat3_t b = {{{0}}};
    double sigma, z[3], ws = 0.0;

    if ((body_vectors == NULL) || (inertial_vectors == NULL) || (weights == NULL) ||
        (davenport_k == NULL) || (weight_sum == NULL)) {
        if (davenport_k != NULL) {
            for (i = 0; i < 4; i++)
                for (j = 0; j < 4; j++)
                    davenport_k->m[i][j] = 0.0;
        }
        if (weight_sum != NULL)
            *weight_sum = 0.0;
        return ADCS_E_NULL;
    }
    if ((count < 2U) || (count > 32U)) {
        for (i = 0; i < 4; i++)
            for (j = 0; j < 4; j++)
                davenport_k->m[i][j] = 0.0;
        *weight_sum = 0.0;
        return ADCS_E_RANGE;
    }
    for (n = 0; n < count; n++) {
        adcs_vec3_t bn, in;
        adcs_mat3_t o;
        if ((!isfinite(weights[n])) || (weights[n] <= 0.0) ||
            (!adcs_is_finite_vec3(&body_vectors[n])) ||
            (!adcs_is_finite_vec3(&inertial_vectors[n])) ||
            (adcs_vec3_normalize(&body_vectors[n], ADCS_EPS_NORM, &bn) != ADCS_OK) ||
            (adcs_vec3_normalize(&inertial_vectors[n], ADCS_EPS_NORM, &in) != ADCS_OK)) {
            for (i = 0; i < 4; i++)
                for (j = 0; j < 4; j++)
                    davenport_k->m[i][j] = 0.0;
            *weight_sum = 0.0;
            return ADCS_E_RANGE;
        }
        ws += weights[n];
        o = adcs_mat3_outer(&bn, &in);
        for (i = 0; i < 3; i++)
            for (j = 0; j < 3; j++)
                b.m[i][j] += weights[n] * o.m[i][j];
    }
    sigma = b.m[0][0] + b.m[1][1] + b.m[2][2];
    z[0] = b.m[1][2] - b.m[2][1];
    z[1] = b.m[2][0] - b.m[0][2];
    z[2] = b.m[0][1] - b.m[1][0];
    davenport_k->m[0][0] = sigma;
    for (i = 0; i < 3; i++) {
        davenport_k->m[0][i + 1] = z[i];
        davenport_k->m[i + 1][0] = z[i];
        for (j = 0; j < 3; j++)
            davenport_k->m[i + 1][j + 1] =
                b.m[i][j] + b.m[j][i] - ((i == j) ? sigma : 0.0);
    }
    *weight_sum = ws;
    return ADCS_OK;
}
